CREATE POLICY "own clip files select" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'clips' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "own clip files insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'clips' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "own clip files delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'clips' AND (storage.foldername(name))[1] = auth.uid()::text);